    Bug 1978531 - Fix refcounting cycle in EwsMessageChannel and OfflineMessageReadListener. r=babolivier

    I didn't need to make both pointers null, but why not fix it twice?

    Differential Revision: https://phabricator.services.mozilla.com/D258177

diff --git a/mailnews/protocols/common/src/OfflineStorage.cpp b/mailnews/protocols/common/src/OfflineStorage.cpp
index e1fb40c61c2..45ee24e48e7 100644
--- a/mailnews/protocols/common/src/OfflineStorage.cpp
+++ b/mailnews/protocols/common/src/OfflineStorage.cpp
@@ -45,6 +45,9 @@ NS_IMETHODIMP OfflineMessageReadListener::OnStopRequest(nsIRequest* request,
     // be downloaded again later.
     mFolder->DiscardOfflineMsg(mMsgKey);
   }
+  // We no longer need the channel. Clean it up so both it and this listener can
+  // be collected.
+  mChannel = nullptr;
   return rv;
 }
 NS_IMETHODIMP OfflineMessageReadListener::OnDataAvailable(
diff --git a/mailnews/protocols/ews/src/EwsMessageChannel.cpp b/mailnews/protocols/ews/src/EwsMessageChannel.cpp
index 3fdc28e5373..51dfb842b7c 100644
--- a/mailnews/protocols/ews/src/EwsMessageChannel.cpp
+++ b/mailnews/protocols/ews/src/EwsMessageChannel.cpp
@@ -572,6 +572,10 @@ nsresult EwsMessageChannel::StartMessageReadFromStore() {
                                           getter_AddRefs(mReadRequest));
   NS_ENSURE_SUCCESS(rv, rv);

+  // We no longer need the listener. Clean it up so both it and this channel can
+  // be collected.
+  mStreamListener = nullptr;
+
   // Apply the same load flags and group that were previously set.
   MOZ_TRY(mReadRequest->SetLoadFlags(mLoadFlags));
   MOZ_TRY(mReadRequest->SetLoadGroup(mLoadGroup));
